FIGURES = {}   # номер -> подпись


def _p_after(el):
    """Создаёт пустой абзац сразу после элемента el и возвращает его объект."""
    from docx.text.paragraph import Paragraph
    new = copy.deepcopy(d.paragraphs[0]._p)
    for child in list(new):
        if not child.tag.endswith('}pPr'):
            new.remove(child)
    el.addnext(new)
    p = Paragraph(new, d.paragraphs[0]._parent)
    for r in list(p.runs):
        r._element.getparent().remove(r._element)
    return p


def place(anchor_el, png, number, caption, width=Cm(15.5)):
    """Вставляет рисунок с подписью после элемента anchor_el."""
    path = os.path.join(FIG, png)
    if not os.path.exists(path):
        raise FileNotFoundError(path)

    # подпись — вставляем первой, потом рисунок над ней
    cap = _p_after(anchor_el)
    cap.paragraph_format.first_line_indent = Cm(0)
    cap.paragraph_format.space_before = Pt(2)
    cap.paragraph_format.space_after = Pt(12)
    cap.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = cap.add_run(f'Рисунок {number} — {caption}')
    r.italic = True
    r.font.size = Pt(10)

    pic = _p_after(anchor_el)
    pic.paragraph_format.first_line_indent = Cm(0)
    pic.paragraph_format.space_before = Pt(10)
    pic.paragraph_format.space_after = Pt(2)
    pic.paragraph_format.keep_with_next = True
    pic.alignment = WD_ALIGN_PARAGRAPH.CENTER
    pic.add_run().add_picture(path, width=width)

    FIGURES[number] = caption
    return pic


def para_by_prefix(prefix):
    for p in d.paragraphs:
        if p.text.strip().startswith(prefix):
            return p
    raise LookupError(prefix)


def table_after(prefix):
    """Возвращает XML-элемент таблицы, следующей за абзацем-подписью."""
    cap = para_by_prefix(prefix)._p
    el = cap.getnext()
    while el is not None and not el.tag.endswith('}tbl'):
        el = el.getnext()
    if el is None:
        raise LookupError('таблица после: ' + prefix)
    return el


def before(prefix):
    """Элемент, ПОСЛЕ которого вставка окажется перед указанным абзацем."""
    p = para_by_prefix(prefix)._p
    prev = p.getprevious()
    if prev is None:
        raise LookupError('нет предшественника: ' + prefix)
    return prev


