# ── Правки редакции 7.0 по указаниям руководителя ───────────────────

def set_text(par, text):
    for r in list(par.runs)[1:]:
        r._element.getparent().remove(r._element)
    if par.runs:
        par.runs[0].text = text
    else:
        par.add_run(text)


def replace_in_doc(old, new):
    """Замена подстроки во всех абзацах и ячейках таблиц."""
    n = 0
    def walk(par):
        nonlocal n
        if old in par.text:
            set_text(par, par.text.replace(old, new))
            n += 1
    for par in d.paragraphs:
        walk(par)
    for t in d.tables:
        for row in t.rows:
            for c in row.cells:
                for par in c.paragraphs:
                    walk(par)
    return n


