# ── Формулы: линейная запись заменяется настоящей математикой Word ──
def F(prefix, *content):
    M.set_formula(para_by_prefix(prefix), *content)

MUL = M.txt(' · ')

# ω = √(a/R)
F('ω = √(a/R)',
  M.r('ω'), M.txt(' = '),
  M.rad([M.frac(M.r('a'), M.r('R'))]), M.txt(' = '),
  M.rad([M.frac([M.num('9,81'), M.txt(' м/с²')], [M.num('5 000'), M.txt(' м')])]),
  M.txt(' ≈ '), M.num('0,0443'), M.txt(' рад/с'))

# f = ω/(2π)
F('f = ω/(2π)',
  M.r('f'), M.txt(' = '), M.frac(M.r('ω'), [M.num('2'), M.r('π')]),
  M.txt(' ≈ '), M.num('0,00705'), M.txt(' Гц ≈ '), M.num('0,423'), M.txt(' об/мин'))

# T = 1/f
F('T = 1/f',
  M.r('T'), M.txt(' = '), M.frac(M.num('1'), M.r('f')),
  M.txt(' ≈ '), M.num('141,9'), M.txt(' с ≈ 2 мин 22 с'))

# ускорение на уровне головы
F('a_головы = ω²',
  M.sub(M.r('a'), M.txt('головы')), M.txt(' = '),
  M.sup(M.r('ω'), M.num('2')), MUL,
  M.delim([M.r('R'), M.txt(' − '), M.r('h')]), M.txt(' = '),
  M.sup(M.num('0,0443'), M.num('2')), MUL, M.num('4 998'),
  M.txt(' ≈ '), M.num('9,806'), M.txt(' м/с²'))

# относительный перепад
F('Δa/a =',
  M.frac([M.r('Δ'), M.r('a')], M.r('a')), M.txt(' = '),
  M.frac([M.num('9,81'), M.txt(' − '), M.num('9,806')], M.num('9,81')),
  M.txt(' ≈ '), M.num('0,04'), M.txt(' %'))

# Кориолис для пешехода
F('a_c = 2ωv',
  M.sub(M.r('a'), M.txt('к')), M.txt(' = '),
  M.num('2'), M.r('ω'), M.r('v'), M.txt(' = '),
  M.num('2'), MUL, M.num('0,0443'), MUL, M.num('1,5'),
  M.txt(' ≈ '), M.num('0,133'), M.txt(' м/с² ≈ '), M.num('0,014'), M.r('g'))

# объём полусфер
F('Объём двух полусфер',
  M.r('V'), M.txt(' = '), M.frac(M.num('4'), M.num('3')), M.r('π'),
  M.sup(M.r('a'), M.num('2')), M.r('c'), M.txt(' = '),
  M.frac(M.num('4'), M.num('3')), M.r('π'), MUL,
  M.sup(M.delim([M.num('5,0'), M.txt(' км')]), M.num('2')), MUL,
  M.delim([M.num('4,5'), M.txt(' км')]),
  M.txt(' ≈ '), M.num('471,2'), M.txt(' км³'))

# барометрическое распределение во вращающейся атмосфере
F('ρ(r) = ρ₀',
  M.r('ρ'), M.delim(M.r('r')), M.txt(' = '),
  M.sub(M.r('ρ'), M.num('0')), MUL, M.txt('exp'),
  M.delim([M.txt('−'), M.frac(
      [M.r('M'), M.sup(M.r('ω'), M.num('2')),
       M.delim([M.sup(M.r('R'), M.num('2')), M.txt(' − '),
                M.sup(M.r('r'), M.num('2'))])],
      [M.num('2'), M.sub(M.r('R'), M.txt('г')), M.r('T')])]))

# кольцевое напряжение
F('σ = q·R/t + ρ·g·R',
  M.r('σ'), M.txt(' = '),
  M.frac([M.r('q'), M.r('R')], M.r('t')), M.txt(' + '),
  M.r('ρ'), M.r('g'), M.r('R'))

# потребная толщина пояса
F('t = q·R / (σ_доп',
  M.r('t'), M.txt(' = '),
  M.frac([M.r('q'), M.r('R')],
         [M.sub(M.r('σ'), M.txt('доп')), M.txt(' − '),
          M.r('ρ'), M.r('g'), M.r('R')]),
  M.txt(' = '),
  M.frac([M.num('153,8'), MUL, M.sup(M.num('10'), M.num('3')), MUL, M.num('5 000')],
         [M.num('1 333'), MUL, M.sup(M.num('10'), M.num('6')), M.txt(' − '),
          M.num('385'), MUL, M.sup(M.num('10'), M.num('6'))]),
  M.txt(' = '), M.num('0,811'), M.txt(' м'))

# проверка напряжения при принятой толщине
F('σ = 153,8·10³',
  M.r('σ'), M.txt(' = '),
  M.frac([M.num('153,8'), MUL, M.sup(M.num('10'), M.num('3')), MUL, M.num('5 000')],
         [M.num('0,85')]),
  M.txt(' + '), M.num('385'), MUL, M.sup(M.num('10'), M.num('6')),
  M.txt(' = '), M.num('905'), M.txt(' + '), M.num('385'),
  M.txt(' = '), M.num('1 290'), M.txt(' МПа'))

# работа подъёма от оси к ободу
F('A = ∫ ω²r dr',
  M.r('A'), M.txt(' = '),
  M.nary('∫', M.num('0'), M.r('R'),
         [M.sup(M.r('ω'), M.num('2')), M.r('r'), M.txt(' d'), M.r('r')]),
  M.txt(' = '),
  M.frac([M.sup(M.r('ω'), M.num('2')), M.sup(M.r('R'), M.num('2'))], M.num('2')),
  M.txt(' = '), M.num('24 520'), M.txt(' Дж/кг'))


