_env_anchor = before('ПРИЛОЖЕНИЕ А. ПРОТОКОЛ РАСЧЁТНОЙ ВЕРИФИКАЦИИ')

def _envtable(anchor, rows):
    """Вставляет таблицу сразу после якоря."""
    t = d.add_table(rows=len(rows), cols=len(rows[0]))
    t.style = 'Table Grid'
    t.autofit = True
    for ri, row in enumerate(rows):
        for ci, val in enumerate(row):
            cell = t.rows[ri].cells[ci]
            set_text(cell.paragraphs[0], str(val))
            for r_ in cell.paragraphs[0].runs:
                r_.font.size = Pt(10)
                if ri == 0 or str(row[0]).startswith('ИТОГО'):
                    r_.bold = True
            cell.paragraphs[0].paragraph_format.first_line_indent = Cm(0)
            cell.paragraphs[0].paragraph_format.space_after = Pt(2)
    anchor.addnext(t._tbl)
    return t


def _envblock(blocks, anchor):
    """Пишет главу от конца к началу: каждый абзац встаёт сразу после якоря."""
    for kind, text in reversed(blocks):
        if kind == 't':
            _envtable(anchor, text)
            continue
        pp = _p_after(anchor)
        if kind == 'h1':
            pp.paragraph_format.first_line_indent = Cm(0)
            pp.paragraph_format.space_before = Pt(20)
            pp.paragraph_format.space_after = Pt(10)
            pp.paragraph_format.keep_with_next = True
            rr_ = pp.add_run(text); rr_.bold = True; rr_.font.size = Pt(15)
        elif kind == 'h2':
            pp.paragraph_format.first_line_indent = Cm(0)
            pp.paragraph_format.space_before = Pt(14)
            pp.paragraph_format.space_after = Pt(6)
            pp.paragraph_format.keep_with_next = True
            rr_ = pp.add_run(text); rr_.bold = True; rr_.font.size = Pt(13)
        else:
            pp.paragraph_format.first_line_indent = Cm(1.25)
            pp.paragraph_format.space_after = Pt(6)
            pp.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
            pp.add_run(text).font.size = Pt(12)

