# ── ревизия 07.09 (24): ОГЛАВЛЕНИЕ СО СТРАНИЦАМИ ───────────────────────
# Заголовки размечены прямым форматированием, стилей Heading нет, поэтому
# уровень структуры (outlineLvl) проставляется постобработкой по regex.
# Номера страниц считает Word: каждая строка оглавления содержит поле
# PAGEREF на закладку у соответствующего заголовка, а в settings.xml
# выставлен updateFields — Word пересчитывает всё при открытии файла.
import re as _re

_RX_H1 = _re.compile(r'^(\d{1,2})\.\s+[А-ЯЁ]')
_RX_H2 = _re.compile(r'^(\d{1,2})\.(\d{1,2})\.\s+\S')
_RX_AP = _re.compile(r'^ПРИЛОЖЕНИЕ\s+[А-ЯЁ]')
_RX_AS = _re.compile(r'^[А-ЯЁ]\.(\d{1,2})\.\s+\S')

def _outline(par, lvl):
    pPr = par._p.get_or_add_pPr()
    for old_ in pPr.findall(qn('w:outlineLvl')):
        pPr.remove(old_)
    el = OxmlElement('w:outlineLvl'); el.set(qn('w:val'), str(lvl))
    pPr.append(el)

def _bookmark(par, bid, name):
    st = OxmlElement('w:bookmarkStart')
    st.set(qn('w:id'), str(bid)); st.set(qn('w:name'), name)
    en = OxmlElement('w:bookmarkEnd'); en.set(qn('w:id'), str(bid))
    pPr_ = par._p.find(qn('w:pPr'))      # w:pPr обязан быть первым по схеме
    if pPr_ is not None:
        pPr_.addnext(st)
    else:
        par._p.insert(0, st)
    par._p.append(en)

_toc_items = []
_bid = 1000
for _par in d.paragraphs:
    _t = _par.text.strip()
    if not _t or len(_t) > 120:
        continue
    if not any(r.bold for r in _par.runs if r.bold is not None):
        continue
    _lvl = None
    if _RX_H1.match(_t) or _RX_AP.match(_t):
        _lvl = 0
    elif _RX_H2.match(_t) or _RX_AS.match(_t):
        _lvl = 1
    if _lvl is None:
        continue
    _outline(_par, _lvl)
    _bid += 1
    _nm = '_Toc%d' % _bid
    _bookmark(_par, _bid, _nm)
    _toc_items.append((_lvl, _t, _nm))

print(f'  размечено заголовков: {len(_toc_items)} '
      f'(гл. {sum(1 for l,_,_ in _toc_items if l==0)}, '
      f'п. {sum(1 for l,_,_ in _toc_items if l==1)})')

_anchor_toc = None
for _par in d.paragraphs:
    if _par.text.strip().startswith('1. ') and any(
            r.bold for r in _par.runs if r.bold is not None):
        _anchor_toc = _par._p; break
if _anchor_toc is None:
    _anchor_toc = d.paragraphs[0]._p

def _p_before(anchor):
    new_ = OxmlElement('w:p'); anchor.addprevious(new_)
    return Paragraph(new_, d)

def _fldchar(par, kind, dirty=False):
    r = OxmlElement('w:r'); f = OxmlElement('w:fldChar')
    f.set(qn('w:fldCharType'), kind)
    if dirty: f.set(qn('w:dirty'), 'true')
    r.append(f); par._p.append(r)

def _instr(par, text):
    r = OxmlElement('w:r'); it = OxmlElement('w:instrText')
    it.set(qn('xml:space'), 'preserve'); it.text = text
    r.append(it); par._p.append(r)

# ── заголовок «СОДЕРЖАНИЕ» ──
_hdr = _p_before(_anchor_toc)
_hdr.paragraph_format.first_line_indent = Cm(0)
_hdr.paragraph_format.space_after = Pt(12)
_hdr.alignment = WD_ALIGN_PARAGRAPH.CENTER
_r = _hdr.add_run('СОДЕРЖАНИЕ'); _r.bold = True; _r.font.size = Pt(15)

# ── поле TOC (Word заменит содержимое при обновлении) ──
_tocp = _p_before(_anchor_toc)
_tocp.paragraph_format.first_line_indent = Cm(0)
_fldchar(_tocp, 'begin', dirty=True)
_instr(_tocp, r' TOC \o "1-2" \h \z \u ')
_fldchar(_tocp, 'separate')

# ── строки оглавления: текст + точки + PAGEREF ──
# Пока Word не обновил поле, номера показывают сами PAGEREF; после
# обновления TOC перестроится целиком. И в том, и в другом случае
# страницы на месте.
_RIGHT_TAB = Cm(16.0)
_toc_runs = {}
for _lvl, _txt, _nm in _toc_items:
    _lp = _p_before(_anchor_toc)
    _pf = _lp.paragraph_format
    _pf.first_line_indent = Cm(0)
    _pf.left_indent = Cm(0.8 if _lvl else 0)
    _pf.space_after = Pt(2)
    _tabs = _lp.paragraph_format.tab_stops
    _tabs.add_tab_stop(_RIGHT_TAB, WD_TAB_ALIGNMENT.RIGHT,
                       WD_TAB_LEADER.DOTS)
    _tr = _lp.add_run(_txt)
    _tr.font.size = Pt(11 if _lvl else 12)
    _tr.bold = (_lvl == 0)
    _lp.add_run('\t').font.size = Pt(11 if _lvl else 12)
    _fldchar(_lp, 'begin')
    _instr(_lp, ' PAGEREF %s \\h ' % _nm)
    _fldchar(_lp, 'separate')
    _nr = _lp.add_run('—')          # заменяется оценкой ниже
    _nr.font.size = Pt(11 if _lvl else 12)
    _nr.bold = (_lvl == 0)
    _toc_runs[_nm] = _nr
    _fldchar(_lp, 'end')

_endp = _p_before(_anchor_toc)
_endp.paragraph_format.first_line_indent = Cm(0)
_fldchar(_endp, 'end')

_brp = _p_before(_anchor_toc)
_brp.paragraph_format.first_line_indent = Cm(0)
_brp.add_run().add_break(WD_BREAK.PAGE)

# ── номера страниц в нижнем колонтитуле ──
for _sec in d.sections:
    _f = _sec.footer
    _f.is_linked_to_previous = False
    _fp = _f.paragraphs[0] if _f.paragraphs else _f.add_paragraph()
    for _old in list(_fp.runs):
        _old._r.getparent().remove(_old._r)
    _fp.alignment = WD_ALIGN_PARAGRAPH.CENTER
    _fp.paragraph_format.first_line_indent = Cm(0)
    _fldchar(_fp, 'begin')
    _instr(_fp, ' PAGE ')
    _fldchar(_fp, 'separate')
    _pr = _fp.add_run('1'); _pr.font.size = Pt(10)
    _fldchar(_fp, 'end')
print('  колонтитул с номерами страниц добавлен')

# ── заставить Word пересчитать поля при открытии ──
_st = d.settings.element
for _old in _st.findall(qn('w:updateFields')):
    _st.remove(_old)
_uf = OxmlElement('w:updateFields'); _uf.set(qn('w:val'), 'true')
_st.append(_uf)
print('  updateFields=true — Word посчитает страницы при открытии')

# ── подстановка оценённых номеров страниц ──────────────────────────────
# Word пересчитает поля PAGEREF при открытии; до этого момента в строках
# должны стоять правдоподобные значения, а не заглушки. Оценка потока
# текста — paginate.py, погрешность единицы страниц.
d.save(DST)                                   # промежуточное сохранение
try:
    import importlib, paginate
    importlib.reload(paginate)
    _marks, _total = paginate.estimate(DST)
    # привести оценку к опорным точкам, снятым в Word
    _names = {}
    for _p2 in d.paragraphs:
        for _bm in _p2._p.findall(qn('w:bookmarkStart')):
            _n2 = _bm.get(qn('w:name'))
            if _n2 and _n2.startswith('_Toc'):
                _names[_n2] = _p2.text.strip()
    _marks = paginate.calibrate(_marks, _names)
    _total = max(_marks.values())
    _miss = 0
    for _nm, _run in _toc_runs.items():
        _pg = _marks.get(_nm)
        if _pg is None:
            _miss += 1
            continue
        _run.text = str(_pg)
    print(f'  номера страниц проставлены (оценка, всего ~{_total} стр.'
          + (f', без номера {_miss}' if _miss else '') + ')')
except Exception as _e:                        # оценка не критична
    print('  ВНИМАНИЕ: оценка страниц не выполнена:', _e)

d.save(DST)

# Последний слой сборки. Поздние исторические блоки этого генератора
# содержат намеренно сохранённые фрагменты старых ревизий; нормализатор
# приводит активный текст и таблицы к единой канонической модели 09.09.2026.
try:
    from final_audit_v7 import apply_audit
    apply_audit(DST)
    print('  финальная сквозная нормализация v7 применена')
except Exception as _e:
    print('  ВНИМАНИЕ: финальная нормализация не выполнена:', _e)
    raise

print('Сохранено:', DST)
print('Рисунков размещено:', len(FIGURES))
print('Абзацев:', len(d.paragraphs), '· таблиц:', len(d.tables))
